CREATE TABLE products (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  attributes JSONB NOT NULL DEFAULT '{}'
);
CREATE INDEX products_attributes_idx ON products USING GIN (attributes);

SELECT name, attributes->>'color' AS color
FROM products
WHERE attributes @> '{"size": "M"}';

CREATE INDEX CONCURRENTLY orders_pending_idx
  ON orders (created_at) WHERE status = 'pending';

CREATE UNIQUE INDEX users_email_idx ON users (lower(email));

CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX products_name_trgm_idx ON products USING GIN (name gin_trgm_ops);
-- acelera: WHERE name ILIKE '%caneca%'

CREATE INDEX orders_customer_idx
  ON orders (customer_id) INCLUDE (total, status);

EXPLAIN SELECT total, status FROM orders WHERE customer_id = 42;
-- Index Only Scan using orders_customer_idx
